  /**
   * v0.2.2 — when set, the avatar + name strip becomes interactive (rendered
   * as `authorComponent` if provided, else `<button type="button">`).
   */
  onAuthorClick?: (story: Story) => void;
  /**
   * v0.2.2 — polymorphic root override for the author tap-target. Defaults
   * to `"button"` when onAuthorClick is set, `"div"` otherwise.
   */
  authorComponent?: ElementType;
  /**
   * v0.3.5 — when set, the kebab button renders in the header right cluster
   * (between mute and close). Tapping it fires this callback (the caller
   * owns the bottom-sheet panel state).
   */
  onKebabClick?: () => void;
}

export function ViewerHeader({
  story,
  item,
  isPaused,
  isMuted,
  onTogglePause,
  onToggleMute,
  onClose,
  formatTime,
  labels,
  onAuthorClick,
  authorComponent,
  onKebabClick,
}: ViewerHeaderProps) {
  const initials = story.username.slice(0, 2).toUpperCase();
  const isInteractive = !!onAuthorClick || !!authorComponent;
  const AuthorRoot: ElementType =
    authorComponent ?? (onAuthorClick ? "button" : "div");
  const authorRootProps: Record<string, unknown> = {
    className: cn(
      "flex items-center gap-3 rounded-full text-left",
      isInteractive &&
        "cursor-pointer transition-opacity hover:opacity-80 focus-visible:opacity-80 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/60",
    ),
  };
  if (onAuthorClick) {
    authorRootProps.onClick = () => onAuthorClick(story);
  }
  if (AuthorRoot === "button") {
    authorRootProps.type = "button";
  }
  return (
    <div className="absolute left-0 right-0 top-4 z-20 flex items-center justify-between px-4 pt-2">
      <AuthorRoot {...authorRootProps}>
        <Avatar className="h-10 w-10 border-2 border-white">
          {story.avatar ? <AvatarImage src={story.avatar} alt="" /> : null}
          <AvatarFallback>{initials}</AvatarFallback>
        </Avatar>
        <div>
          <p className="text-sm font-semibold text-white">{story.username}</p>
          <p className="text-xs text-white/60">
            {formatTime(new Date(story.createdAt))}
          </p>
        </div>
      </AuthorRoot>
      <div className="flex items-center gap-2">
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="h-11 w-11 md:h-9 md:w-9 text-white hover:bg-white/20 hover:text-white"
          onClick={onTogglePause}
          aria-label={isPaused ? labels.play : labels.pause}
        >
          {isPaused ? <Play className="h-4 w-4" /> : <Pause className="h-4 w-4" />}
        </Button>
        {item.type === "video" ? (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="h-11 w-11 md:h-9 md:w-9 text-white hover:bg-white/20 hover:text-white"
            onClick={onToggleMute}
            aria-label={isMuted ? labels.unmute : labels.mute}
            aria-pressed={isMuted}
          >
            {isMuted ? <VolumeX className="h-4 w-4" /> : <Volume2 className="h-4 w-4" />}
          </Button>
        ) : null}
        {onKebabClick ? (
          <Button
            type="button"
            variant="ghost"
            size="icon"
            className="h-11 w-11 md:h-9 md:w-9 text-white hover:bg-white/20 hover:text-white"
            onClick={onKebabClick}
            aria-label={labels.kebabAriaLabel}
          >
            <MoreVertical className="h-5 w-5" />
          </Button>
        ) : null}
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="h-11 w-11 md:h-9 md:w-9 text-white hover:bg-white/20 hover:text-white"
          onClick={onClose}
          aria-label={labels.close}
        >
          <X className="h-5 w-5" />
        </Button>
      </div>
    </div>
  );
}

import type { MouseEvent as ReactMouseEvent } from "react";

export interface TapZonesProps {
  onPrev: () => void;
  onTogglePause: () => void;
  onNext: () => void;
}

/**
 * Three full-height columns (1/3 each) over the item content:
 * - left = previous item
 * - middle = pause toggle
 * - right = next item
 *
 * Lives at z-10 so the header (z-20) and nav arrows (z-20) remain clickable.
 * `tabIndex={-1}` because tap zones are touch affordances; keyboard users
 * use the arrow-key handlers instead. `onMouseDown` preventDefault blocks
 * the click-induced focus that would otherwise leave the focused button
 * trapped inside the `aria-hidden` wrapper (browser console warning).
 */
function preventFocusOnPress(e: ReactMouseEvent<HTMLButtonElement>) {
  e.preventDefault();
}

export function TapZones({ onPrev, onTogglePause, onNext }: TapZonesProps) {
  return (
    <div className="absolute inset-0 z-10 flex" aria-hidden="true">
      <button
        type="button"
        className="h-full w-1/3 cursor-pointer"
        onClick={(e) => {
          e.stopPropagation();
          onPrev();
        }}
        onMouseDown={preventFocusOnPress}
        tabIndex={-1}
      />
      <button
        type="button"
        className="h-full w-1/3 cursor-pointer"
        onClick={(e) => {
          e.stopPropagation();
          onTogglePause();
        }}
        onMouseDown={preventFocusOnPress}
        tabIndex={-1}
      />
      <button
        type="button"
        className="h-full w-1/3 cursor-pointer"
        onClick={(e) => {
          e.stopPropagation();
          onNext();
        }}
        onMouseDown={preventFocusOnPress}
        tabIndex={-1}
      />
    </div>
  );
}

